import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:introduction_screen/introduction_screen.dart';import '../Utils/Extensions/int_extension.dart';class AppConstants {  static DotsDecorator get dotsDecoration {    return DotsDecorator(      size: Size(8.w, 8.h),      activeSize: Size(24.w, 8.h),      color: Colors.white54,      activeColor: Colors.white,      spacing: EdgeInsets.symmetric(horizontal: 4.w),      activeShape: RoundedRectangleBorder(        borderRadius: BorderRadius.circular(25.0),      ),    );  }  static SliverGridDelegate gridDelegateSmallBuilder(      NumbersOfCrossAxisCount numbersOfCrossAxisCount) {    final count = numbersOfCrossAxisCount.value[0];    final ratio = numbersOfCrossAxisCount.value[1];    return SliverGridDelegateWithFixedCrossAxisCount(      crossAxisCount: (count.toInt()).crossAxisCountBuilder,      mainAxisSpacing: 16.h,      crossAxisSpacing: 21.w,      childAspectRatio: ratio.toDouble(),    );  }}enum NumbersOfCrossAxisCount {  small([150, (52 / 75)]),  large([400, 2.5]);  final List<num> value;  const NumbersOfCrossAxisCount(this.value);}